# [independent tester, 2026-11-14] LOGGING-ONLY wrapper around simB2hx_r2 (the other agent's revision 2 model, generated by
# make_simB2hx_r2.py). No change to the dynamics or to any decision: it only records, at the end of every grab,
#   dock_dys_mm      true sideways bin offset (mm) at each docking attempt (first arrival first)
#   nib_y_mm         sideways position of the nib in the bin frame (mm) at the end of the grab (what the seated() band tests)
#   seated50         seated() re-evaluated with the ORIGINAL 640 mm comb band (tooth_hw 0.32 -> |y| band 50 mm on the clip-lid bin)
#   captured50       seated50 and wheel clearance > 30 mm; false_hold50 = claim and not captured50
import importlib, os
_M = importlib.import_module('simB2hx_r2')
globals().update({k: v for k, v in _M.__dict__.items() if not k.startswith('__')})
# record every docking attempt: approach() sets R.dock_dy before deciding on a re-approach; wrap RunnerB.ev to catch the 'docked:' event
_ev0 = _M.RunnerB.ev
def _ev(R, msg, *a, **k):
    if isinstance(msg, str) and msg.startswith('docked:'):
        R.__dict__.setdefault('_dys', []).append(getattr(R, 'dock_dy', None))
    return _ev0(R, msg, *a, **k)
_M.RunnerB.ev = _ev
_grab0 = _M.grab
def grab(R, seed=0):
    out = _grab0(R, seed=seed)
    try:
        S = R.s; G = _M.GEO
        out['dock_dys_mm'] = list(getattr(R, '_dys', []))
        out['nib_y_mm'] = round(float(S.nib_in_bin()[1]) * 1000, 1)
        hw = G['tooth_hw']; G['tooth_hw'] = 0.32
        try: s50 = bool(S.seated())
        finally: G['tooth_hw'] = hw
        out['seated50'] = s50; out['captured50'] = bool(s50 and S.wheel_clear() > 0.030)
        out['false_hold50'] = bool(out.get('claim') and not out['captured50'])
    except Exception as e:
        out['log_err'] = repr(e)
    return out
_M.grab = grab
